alter table public.sales_orders add column if not exists checkout_key text;
create unique index if not exists sales_orders_company_checkout_key_uq on public.sales_orders(company_id,checkout_key) where checkout_key is not null;
create table if not exists public.sales_shift_cash_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,shift_id uuid not null references public.sales_shifts(id) on delete cascade,movement_type text not null check(movement_type in ('cash_in','cash_out')),amount numeric not null check(amount>0),reason text not null,created_by uuid,created_at timestamptz not null default now());
create index if not exists sales_shift_cash_movements_shift_idx on public.sales_shift_cash_movements(company_id,shift_id,created_at);
create table if not exists public.sales_refund_lines(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,refund_id uuid not null references public.sales_refunds(id) on delete cascade,order_line_id uuid not null references public.sales_order_lines(id),quantity numeric not null check(quantity>0),amount numeric not null default 0,tax_amount numeric not null default 0,cost_amount numeric not null default 0,created_at timestamptz not null default now());
create index if not exists sales_refund_lines_refund_idx on public.sales_refund_lines(company_id,refund_id);